import React, { useReducer, useEffect, useState } from "react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";
import Loading from "../Components/Loading";

const init = {
  loading: false,
  err: false,
  data: [],
};

const reducer = (state, { type, payload }) => {
  switch (type) {
    case "FETCH_LOADING":
      return {
        loading: true,
        err: false,
        data: [],
      };

    case "FETCH_SUCCESSFUL":
      return {
        loading: false,
        err: false,
        data: payload,
      };

    case "FETCH_UNSUCCESSFUL":
      return {
        loading: false,
        err: true,
        data: [],
      };
    default:
      throw new Error("Invalid Action type");
  }
};

const Courses = () => {
  let baseUrl = `https://rctmockapi.onrender.com/courses`;
  const [state, dispatch] = useReducer(reducer, init);
  const [category, setCategory] = useState("");
  const [price, setPrice] = useState("");
  const navigate = useNavigate();

  function fetchCourses(url) {
    dispatch({ type: "FETCH_LOADING" });
    axios
      .get(url)
      .then((res) => {
        dispatch({ type: "FETCH_SUCCESSFUL", payload: res.data });
      })
      .catch((err) => {
        dispatch({ type: "FETCH_UNSUCCESSFUL" });
        console.log(err);
      });
  }

  const { loading, err, data } = state;

  useEffect(() => {
    let url = baseUrl;
    if (price && category) {
      url = `${baseUrl}?category=${category}&price_lte=${price}`;
    } else if (category) {
      url = `${baseUrl}?category=${category}`;
    } else if (price) {
      url = `${baseUrl}?price_lte=${price}`;
    }

    fetchCourses(url);
  }, [category, price]);

  function handleReset() {
    setCategory("");
    setPrice("");
  }

  function handleEnroll() {
    navigate("/signup");
  }

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="flex flex-col items-center mb-8">
          <h1 className="text-3xl md:text-5xl font-extrabold text-[#304b62] my-6">
            Our Courses
          </h1>
          <div className="flex flex-col md:flex-row items-center gap-4">
            <select
              value={category}
              className="text-[#304b62] font-bold text-base md:text-lg bg-white border border-slate-300 rounded-md px-4 py-2 focus:outline-none focus:ring-2 focus:ring-[#304b62]"
              onChange={(e) => setCategory(e.target.value)}
            >
              <option value="">Filter By Category</option>
              <option value="Art">Art</option>
              <option value="Dance">Dance</option>
              <option value="Music">Music</option>
              <option value="Academic">Academic</option>
            </select>
            <select
              value={price}
              className="text-[#304b62] font-bold text-base md:text-lg bg-white border border-slate-300 rounded-md px-4 py-2 focus:outline-none focus:ring-2 focus:ring-[#304b62]"
              onChange={(e) => setPrice(e.target.value)}
            >
              <option value="">Filter By Price</option>
              <option value="500">Less than 500</option>
              <option value="1000">Less than 1000</option>
            </select>
            <button
              onClick={handleReset}
              className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-5 py-2 rounded-md transition-colors"
            >
              Reset Filters
            </button>
          </div>
        </div>
        <Loading />
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      {/* Header and Filters */}
      <div className="flex flex-col items-center mb-10">
        <h1 className="text-3xl md:text-5xl font-extrabold text-[#304b62] my-6">
          Our Courses
        </h1>
        <div className="flex flex-col md:flex-row items-center gap-4">
          <select
            value={category}
            className="text-[#304b62] font-bold text-base md:text-lg bg-white border border-slate-300 rounded-md px-4 py-2 focus:outline-none focus:ring-2 focus:ring-[#304b62]"
            onChange={(e) => setCategory(e.target.value)}
          >
            <option value="">Filter By Category</option>
            <option value="Art">Art</option>
            <option value="Dance">Dance</option>
            <option value="Music">Music</option>
            <option value="Academic">Academic</option>
          </select>
          <select
            value={price}
            className="text-[#304b62] font-bold text-base md:text-lg bg-white border border-slate-300 rounded-md px-4 py-2 focus:outline-none focus:ring-2 focus:ring-[#304b62]"
            onChange={(e) => setPrice(e.target.value)}
          >
            <option value="">Filter By Price</option>
            <option value="500">Less than 500</option>
            <option value="1000">Less than 1000</option>
          </select>
          <button
            onClick={handleReset}
            className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-5 py-2 rounded-md transition-colors"
          >
            Reset Filters
          </button>
        </div>
      </div>

      {/* Course Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {data.map((course) => (
          <div
            key={course.id}
            className="bg-[#304b62] text-white rounded-xl overflow-hidden shadow-lg flex flex-col justify-between"
          >
            <div className="p-6">
              <img
                src={course.image}
                alt={course.courseName}
                className="h-[220px] w-full object-cover rounded-lg mb-4"
              />
              <div className="space-y-2 mt-4">
                <h3 className="text-xl font-bold">{course.courseName}</h3>
                <p className="text-sm text-slate-300">{course.TagLine}</p>
              </div>
            </div>

            <div className="border-t border-slate-500/50 p-6 flex items-center justify-between gap-2">
              <Link
                to={`/courses/${course.id}`}
                className="bg-[#d49539] hover:bg-[#c0832d] text-black font-bold text-sm px-4 py-2 rounded-md transition-colors"
              >
                View Details
              </Link>
              <button
                onClick={handleEnroll}
                className="bg-white hover:bg-slate-100 text-black font-bold text-sm px-4 py-2 rounded-md transition-colors"
              >
                Enroll
              </button>
              <span className="text-xl font-extrabold text-white">
                ₹{course.price}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Courses;
